// Matches ANSI color/escape sequences
// eslint-disable-next-line no-control-regex
const ANSI_COLOR_REGEX = /\x1B\[[0-9;]*[A-Za-z]/g;
// Matches remaining control characters
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS_REGEX = /[\x00-\x1F\x7F]/g;

const READ_LOGS_TIMEOUT_MS = 30 * 1000;

/**
 * @description Reads Zigbee2MQTT container logs and detects fatal errors.
 * @param {string} containerId - Container id.
 * @returns {Promise} Resolve when the logs have been read (or on timeout/error).
 * @example
 * await this.readZ2mContainerLogs(containerId);
 */
async function readZ2mContainerLogs(containerId) {
  let stream;

  try {
    stream = await this.gladys.system.getContainerLogs(containerId, { follow: true });
  } catch (e) {
    logger.debug('Unable to read Zigbee2mqtt container logs:', e);
    this.z2mContainerError = null;
    this.emitStatusEvent();
    return;
  }

  await new Promise((resolve) => {
    let finished = false;
    let knownError = null;
    let lastErrorLine = null;
    let buffer = '';

    const finish = (forcedError) => {
      if (finished) {
        return;
      }
      finished = true;
      clearTimeout(timeout);

      if (forcedError !== undefined) {
        this.z2mContainerError = forcedError;
      } else if (knownError) {
        // A known error code takes precedence over any generic error line
        this.z2mContainerError = knownError;
      } else if (lastErrorLine) {
        this.z2mContainerError = { code: null, message: lastErrorLine };
      } else {
        this.z2mContainerError = null;
      }

      try {
        stream.destroy();
      } catch (e) {
        // Ignore errors while destroying the stream
      }

      this.emitStatusEvent();
      resolve();
    };

    const processLine = (rawLine) => {
      // Strip the Docker stream prefix byte, ANSI color codes and remaining control chars
      const cleaned = rawLine
        .slice(1)
        .replace(ANSI_COLOR_REGEX, '')
        .replace(CONTROL_CHARS_REGEX, '');

      if (
        cleaned.includes('Adapter EZSP protocol version') &&
        cleaned.includes('is not supported by Host')
      ) {
        knownError = { code: 'EZSP_PROTOCOL_VERSION', message: null };
        // Known error detected: stop reading and destroy the stream
        finish();
        return;
      }

      if (/error:/i.test(cleaned)) {
        // Keep only the last matched error line
        lastErrorLine = cleaned.trim();
      }
    };

    const timeout = setTimeout(() => finish(), READ_LOGS_TIMEOUT_MS);

    stream.on('data', (chunk) => {
      buffer += chunk.toString();
      const lines = buffer.split('\n');
      buffer = lines.pop();
      lines.forEach(processLine);
    });

    stream.on('end', () => {
      if (buffer.length > 0) {
        processLine(buffer);
        buffer = '';
      }
      finish();
    });

    stream.on('error', () => {
      finish(null);
    });
  });
}

module.exports = {
  readZ2mContainerLogs,
};
